package main

import("context";"errors";"os";"strings";"time";"github.com/jackc/pgx/v5/pgxpool")
type postgresTrendStore struct{pool *pgxpool.Pool}
func newTrendStore(ctx context.Context)(TrendStore,func(),error){mode:=strings.ToLower(strings.TrimSpace(os.Getenv("MUSIC_TRENDS_STORE")));if mode==""{mode="memory"};if mode!="postgres"{return &memoryTrendStore{},func(){},nil};dsn:=strings.TrimSpace(os.Getenv("MUSIC_DATABASE_URL"));if dsn==""{dsn=strings.TrimSpace(os.Getenv("DATABASE_URL"))};if dsn==""{return nil,func(){},errors.New("MUSIC_DATABASE_URL or DATABASE_URL is required when MUSIC_TRENDS_STORE=postgres")};if ctx==nil{ctx=context.Background()};cfg,err:=pgxpool.ParseConfig(dsn);if err!=nil{return nil,func(){},err};cfg.MaxConns=10;cfg.MinConns=1;cfg.MaxConnIdleTime=5*time.Minute;pool,err:=pgxpool.NewWithConfig(ctx,cfg);if err!=nil{return nil,func(){},err};pingCtx,cancel:=context.WithTimeout(ctx,5*time.Second);defer cancel();if err:=pool.Ping(pingCtx);err!=nil{pool.Close();return nil,func(){},err};if err:=ensureTrendSchema(ctx,pool);err!=nil{pool.Close();return nil,func(){},err};return &postgresTrendStore{pool:pool},pool.Close,nil}
func ensureTrendSchema(ctx context.Context,pool *pgxpool.Pool)error{_,err:=pool.Exec(ctx,`CREATE TABLE IF NOT EXISTS music_events (id BIGSERIAL PRIMARY KEY, track_id TEXT NOT NULL, event_type TEXT NOT NULL, country TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', user_id TEXT NOT NULL DEFAULT '', occurred_at TIMESTAMPTZ NOT NULL); CREATE INDEX IF NOT EXISTS idx_music_events_track_time ON music_events (track_id, occurred_at); CREATE INDEX IF NOT EXISTS idx_music_events_geo_time ON music_events (country, city, occurred_at); CREATE INDEX IF NOT EXISTS idx_music_events_time ON music_events (occurred_at);`);return err}
func(s *postgresTrendStore)Add(e MusicEvent)error{if e.At.IsZero(){e.At=time.Now().UTC()};e.Type=strings.ToLower(strings.TrimSpace(e.Type));if _,ok:=eventWeights[e.Type];!ok{return nil};_,err:=s.pool.Exec(context.Background(),`INSERT INTO music_events (track_id,event_type,country,city,user_id,occurred_at) VALUES ($1,$2,$3,$4,$5,$6)`,e.TrackID,e.Type,strings.ToUpper(strings.TrimSpace(e.Country)),strings.TrimSpace(e.City),strings.TrimSpace(e.UserID),e.At.UTC());return err}
func(s *postgresTrendStore)Rank(country,city string,window time.Duration)([]TrendItem,error){if window<=0{return []TrendItem{},nil};now:=time.Now().UTC();cutoff:=now.Add(-window);previous:=cutoff.Add(-window);args:=[]any{previous,cutoff,now};filters:="";if country!=""{args=append(args,strings.ToUpper(strings.TrimSpace(country)));filters+=" AND country=$4"};if city!=""{args=append(args,strings.TrimSpace(city));if country!=""{filters+=" AND city=$5"}else{filters+=" AND city=$4"}};q:=`SELECT track_id,COALESCE(SUM(CASE WHEN occurred_at >= $2 AND occurred_at <= $3 THEN CASE event_type WHEN 'play' THEN 1 WHEN 'complete' THEN 2 WHEN 'replay' THEN 2 WHEN 'use' THEN 8 WHEN 'save' THEN 5 WHEN 'share' THEN 6 WHEN 'search' THEN 0.25 ELSE 0 END ELSE 0 END),0),COALESCE(SUM(CASE WHEN occurred_at >= $2 AND occurred_at <= $3 AND event_type IN ('play','complete','replay') THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN occurred_at >= $2 AND occurred_at <= $3 AND event_type='use' THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN occurred_at >= $2 AND occurred_at <= $3 AND event_type='save' THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN occurred_at >= $2 AND occurred_at <= $3 AND event_type='share' THEN 1 ELSE 0 END),0),COALESCE(SUM(CASE WHEN occurred_at >= $1 AND occurred_at < $2 THEN CASE event_type WHEN 'play' THEN 1 WHEN 'complete' THEN 2 WHEN 'replay' THEN 2 WHEN 'use' THEN 8 WHEN 'save' THEN 5 WHEN 'share' THEN 6 WHEN 'search' THEN 0.25 ELSE 0 END ELSE 0 END),0) FROM music_events WHERE occurred_at >= $1 AND occurred_at <= $3`+filters+` GROUP BY track_id ORDER BY 2 DESC,track_id ASC LIMIT 50`;rows,err:=s.pool.Query(context.Background(),q,args...);if err!=nil{return nil,err};defer rows.Close();out:=make([]TrendItem,0,50);for rows.Next(){var item TrendItem;var previousScore float64;if err:=rows.Scan(&item.TrackID,&item.Score,&item.Plays,&item.Uses,&item.Saves,&item.Shares,&previousScore);err!=nil{return nil,err};if previousScore>0{item.Growth24h=(item.Score-previousScore)/previousScore*100};item.Country=country;item.City=city;out=append(out,item)};return out,rows.Err()}
